<template><div class="panel"><div class="toolbar"><el-input v-model="q.keyword" placeholder="订单号/收货人/手机号" clearable style="width:250px"/><el-select v-model="q.status" clearable placeholder="订单状态" style="width:150px"><el-option v-for="(v,k) in statusText" :key="k" :label="v" :value="k"/></el-select><el-button @click="load">查询</el-button></div><el-table :data="items"><el-table-column prop="orderNo" label="订单号" min-width="175"/><el-table-column label="收货人" width="130"><template #default="s">{{s.row.receiver}}<div class="muted" style="font-size:11px">{{s.row.phone}}</div></template></el-table-column><el-table-column label="商品" min-width="220"><template #default="s"><div v-for="x in s.row.items.slice(0,2)" :key="x.id" style="font-size:12px;margin:3px 0">{{x.name}} {{x.specText}} × {{x.quantity}}</div></template></el-table-column><el-table-column label="实付" width="100"><template #default="s">¥{{s.row.totalAmount}}</template></el-table-column><el-table-column label="状态" width="110"><template #default="s"><el-tag>{{statusText[s.row.status]}}</el-tag></template></el-table-column><el-table-column label="下单时间" width="175"><template #default="s">{{new Date(s.row.createdAt).toLocaleString()}}</template></el-table-column><el-table-column label="操作" width="110"><template #default="s"><el-button link type="primary" @click="edit(s.row)">处理</el-button></template></el-table-column></el-table><div style="display:flex;justify-content:flex-end;margin-top:18px"><el-pagination background layout="prev,pager,next,total" :total="total" :page-size="q.pageSize" v-model:current-page="q.page" @current-change="load"/></div></div><el-dialog v-model="visible" title="处理订单" width="520px"><el-form label-position="top"><el-form-item label="订单状态"><el-select v-model="form.status" style="width:100%"><el-option v-for="(v,k) in statusText" :key="k" :label="v" :value="k"/></el-select></el-form-item><el-form-item label="物流公司"><el-input v-model="form.logisticsName" placeholder="例如 顺丰速运"/></el-form-item><el-form-item label="物流单号"><el-input v-model="form.trackingNo"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></template>
<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{api}from'../api';import{ElMessage}from'element-plus';const statusText:any={PENDING_PAYMENT:'待付款',PAID:'待发货',PREPARING:'备货中',SHIPPED:'已发货',COMPLETED:'已完成',CANCELLED:'已取消',REFUNDING:'退款中',REFUNDED:'已退款'};const items=ref<any[]>([]),total=ref(0),visible=ref(false),q=reactive({keyword:'',status:'',page:1,pageSize:20}),form=reactive<any>({id:0,status:'PAID',logisticsName:'',trackingNo:''});async function load(){const d:any=await api.get('/admin/orders',{params:q});items.value=d.items;total.value=d.total}function edit(r:any){Object.assign(form,{id:r.id,status:r.status,logisticsName:r.logisticsName||'',trackingNo:r.trackingNo||''});visible.value=true}async function save(){await api.put(`/admin/orders/${form.id}/status`,form);visible.value=false;ElMessage.success('订单已更新');load()}onMounted(load)</script>
